def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('NUM', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        if pos < len(tokens):
            return tokens[pos]
        return (None, None)

    def parse_expr():
        nonlocal pos
        val = parse_term()
        while True:
            t, _ = peek()
            if t == '+' or t == '-':
                pos += 1
                rhs = parse_term()
                if t == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    def parse_term():
        nonlocal pos
        val = parse_unary()
        while True:
            t, _ = peek()
            if t == '*' or t == '/':
                pos += 1
                rhs = parse_unary()
                if t == '*':
                    val = val * rhs
                else:
                    sign = -1 if (val < 0) != (rhs < 0) else 1
                    val = sign * (abs(val) // abs(rhs))
            else:
                break
        return val

    def parse_unary():
        nonlocal pos
        t, _ = peek()
        if t == '-':
            pos += 1
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal pos
        t, v = peek()
        if t == 'NUM':
            pos += 1
            return v
        if t == '(':
            pos += 1
            val = parse_expr()
            t2, _ = peek()
            if t2 != ')':
                raise ValueError("Expected ')'")
            pos += 1
            return val
        raise ValueError(f"Unexpected token: {t}")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

